SELECT p.part_id,p.part_nm,p.hq_yn,p.use_yn,u.user_nm AS leader_name,s.prft_dstrb_rt,s.sales_exps_amt
FROM TB_BS_PART p LEFT JOIN LATERAL (
  SELECT x.* FROM TB_BS_PART_STD x WHERE x.part_id=p.part_id AND x.aply_bgn_ym <= #{month}
    AND (x.aply_end_ym IS NULL OR x.aply_end_ym >= #{month}) ORDER BY x.aply_bgn_ym DESC LIMIT 1
) s ON true LEFT JOIN TB_SY_USER u ON u.user_id=s.part_ldr_user_id ORDER BY p.part_nm, p.part_id

SELECT s.setl_stat_cd,s.cnfm_user_id,u.user_nm AS cnfm_user_nm,s.cnfm_dttm,s.cncl_rsn,s.corp_card_amt,s.part_prft_amt,s.mod_dttm
FROM TB_CO_PART_SETL s LEFT JOIN TB_SY_USER u ON u.user_id=s.cnfm_user_id
WHERE s.part_id=#{partId} AND s.setl_ym=#{month}

mapper.update:
UPDATE TB_CO_PART_SETL SET setl_stat_cd='WORK',cncl_rsn=#{reason},cnfm_user_id=NULL,cnfm_dttm=NULL,
  mod_user_id=#{mutation.actor},mod_dttm=GREATEST(clock_timestamp(),COALESCE(mod_dttm,reg_dttm)+interval '1 microsecond')
WHERE part_id=#{mutation.key.partId} AND setl_ym=#{mutation.key.month}
  AND mod_dttm IS NOT DISTINCT FROM #{mutation.version,jdbcType=TIMESTAMP_WITH_TIMEZONE}
  AND setl_stat_cd IN ('CNFM','AUTO')
